-- RBAC 7/8 (epic #183, issue #190): credential and session hygiene.
-- Expand phase, compatible with the previous app version: every new column is
-- nullable or has a default, the only relaxed constraint is
-- api_keys.key NOT NULL (the previous app always supplies a key and reads it
-- with a plain WHERE key = ..., both unaffected), and nothing is dropped.
--
-- Generated by drizzle-kit, then made idempotent (IF NOT EXISTS) and extended
-- with the key-hash backfill. Re-running the migration is a no-op.

-- 1. API keys: SHA-256 hash + display prefix, scopes, expiry and revocation.
--    The plaintext column stays (dual-read for one release); the contract
--    phase (RBAC 8/8) drops it.
ALTER TABLE "bingoscape-next_api_keys" ALTER COLUMN "key" DROP NOT NULL;--> statement-breakpoint
ALTER TABLE "bingoscape-next_api_keys" ADD COLUMN IF NOT EXISTS "key_hash" varchar(64);--> statement-breakpoint
ALTER TABLE "bingoscape-next_api_keys" ADD COLUMN IF NOT EXISTS "key_prefix" varchar(16);--> statement-breakpoint
ALTER TABLE "bingoscape-next_api_keys" ADD COLUMN IF NOT EXISTS "scopes" text[] DEFAULT ARRAY['read','submit']::text[] NOT NULL;--> statement-breakpoint
ALTER TABLE "bingoscape-next_api_keys" ADD COLUMN IF NOT EXISTS "expires_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "bingoscape-next_api_keys" ADD COLUMN IF NOT EXISTS "revoked_at" timestamp with time zone;--> statement-breakpoint

-- 2. Backfill the hash and prefix of existing keys. PostgreSQL 11+ has the
--    built-in sha256(bytea), so no pgcrypto extension is needed. The hash is
--    the lower-case hex SHA-256 of the key's UTF-8 bytes, exactly what
--    hashApiKey() in src/lib/api-key.ts computes. Rows the previous app
--    creates after this point have no hash; the app backfills them on first
--    use (legacy dual-read).
UPDATE "bingoscape-next_api_keys"
SET "key_hash" = encode(sha256(convert_to("key", 'UTF8')), 'hex'),
    "key_prefix" = left("key", 8)
WHERE "key" IS NOT NULL AND "key_hash" IS NULL;--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "api_keys_key_hash_unique" ON "bingoscape-next_api_keys" USING btree ("key_hash");--> statement-breakpoint

-- 3. Sessions and the super-admin allowlist.
ALTER TABLE "bingoscape-next_user" ADD COLUMN IF NOT EXISTS "session_revoked_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "bingoscape-next_user" ADD COLUMN IF NOT EXISTS "provider_verified_email" varchar(255);
